package com.innovatus.studentrecords.controller; import com.innovatus.studentrecords.dao.*; import com.innovatus.studentrecords.model.Student; import com.innovatus.studentrecords.service.ExcelService; import java.io.*; import java.util.*; public class UploadController {public List<Student> preview(File f,int u)throws Exception{return new ExcelService().read(f,u);}public void save(File f,List<Student>s)throws Exception{new StudentDAO().insertAll(s);Student x=s.get(0);new UploadHistoryDAO().create(x.uploadedBy(),f.getName(),x.department(),x.batch(),x.year(),s.size());}}
